-- ============================================================
-- V-Farms resort schema: migrations 059, 060, 061, 062, 063, 064, 065 in one transaction.
-- GENERATED by scripts/bundle-resort-migrations.mjs — do not edit by hand.
--
-- Paste into Supabase → SQL Editor and run. Additive and idempotent:
-- creates tables, functions and policies; deletes no data. If any
-- statement fails, the whole transaction rolls back.
-- Requires migrations 001–058 (the base CRM schema) to be applied first.
-- Undo 063/064: supabase/rollback/063_vfarms_resort_automations_down.sql
-- (re-run 062 first).
-- ============================================================

BEGIN;

DO $$
BEGIN
  IF to_regprocedure('public.resolve_inbound_context(text, text, text[], jsonb)') IS NULL THEN
    RAISE EXCEPTION 'Base schema incomplete: apply supabase/migrations 001–058 before this bundle.';
  END IF;
END $$;

-- >>>>>>>>>> 059_vfarms_resort_schema.sql
-- ============================================================
-- V-Farms resort booking schema.
--
-- The estate is ONE reservable resource. Overnight stays, events,
-- temporary holds and manual/maintenance blocks all occupy time on the
-- same calendar (availability_blocks). An exclusion constraint makes
-- two overlapping ACTIVE blocks impossible for the same account, so
-- double-booking is prevented by the database even under concurrent
-- requests. The five guest rooms are descriptive (property_settings.
-- room_count / building_description), never separate inventory.
--
-- Every business fact (rates, capacity, times, amenities, policies) is
-- nullable / inactive by default. NULL means "Not configured" and the
-- application must not promise anything based on it.
--
-- Tenancy follows migration 017: every table carries account_id and is
-- protected by is_account_member(account_id, min_role).
--   viewer : read
--   agent  : reservation manager — leads, bookings, conversations
--   admin  : property, pricing, settings (owner inherits admin)
--
-- Idempotent — safe to run multiple times.
-- ============================================================

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- A project that never ran this migration can still hold unrelated tables
-- with the same names (e.g. a `leads` table from an earlier CRM setup).
-- CREATE TABLE IF NOT EXISTS would silently keep them and later statements
-- would fail on their columns. They are renamed to legacy_pre_vfarms_<name>
-- (indexes and sequences too) with data and policies untouched. Undo by
-- renaming back. No-op once property_settings exists.
DO $$
DECLARE
  t TEXT;
  r RECORD;
BEGIN
  IF to_regclass('public.property_settings') IS NOT NULL THEN
    RETURN;
  END IF;
  FOREACH t IN ARRAY ARRAY[
    'property_media', 'amenities', 'property_faqs', 'pricing_rules', 'seasonal_rates',
    'event_packages', 'addons', 'leads', 'lead_notes', 'conversation_states', 'bookings', 'booking_guests',
    'booking_quotes', 'event_requests', 'availability_blocks', 'payments', 'refunds', 'notification_jobs',
    'audit_logs', 'webhook_events', 'consent_records'
  ] LOOP
    CONTINUE WHEN to_regclass(format('public.%I', t)) IS NULL;
    IF to_regclass(format('public.%I', 'legacy_pre_vfarms_' || t)) IS NOT NULL THEN
      RAISE EXCEPTION 'public.% predates V-Farms and public.legacy_pre_vfarms_% already exists; rename one of them and re-run.', t, t;
    END IF;
    FOR r IN
      SELECT c.relname, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'INDEX' END AS kind
      FROM pg_class c
      WHERE c.oid IN (SELECT indexrelid FROM pg_index WHERE indrelid = format('public.%I', t)::regclass)
         OR c.oid IN (SELECT objid FROM pg_depend WHERE refobjid = format('public.%I', t)::regclass AND deptype IN ('a', 'i') AND classid = 'pg_class'::regclass)
            AND c.relkind = 'S'
    LOOP
      EXECUTE format('ALTER %s public.%I RENAME TO %I', r.kind, r.relname, left('legacy_pre_vfarms_' || r.relname, 63));
    END LOOP;
    EXECUTE format('ALTER TABLE public.%I RENAME TO %I', t, 'legacy_pre_vfarms_' || t);
    RAISE NOTICE 'Kept pre-existing public.% as public.legacy_pre_vfarms_% (data untouched).', t, t;
  END LOOP;
END $$;

-- ============================================================
-- PROPERTY SETTINGS (one row per account)
-- ============================================================
CREATE TABLE IF NOT EXISTS property_settings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL UNIQUE REFERENCES accounts(id) ON DELETE CASCADE,
  resort_name TEXT NOT NULL DEFAULT 'V-Farms',
  tagline TEXT,
  description TEXT,
  farm_description TEXT,
  building_description TEXT,
  room_count INTEGER CHECK (room_count IS NULL OR room_count > 0),
  property_area_acres NUMERIC(6,2) CHECK (property_area_acres IS NULL OR property_area_acres > 0),
  address TEXT,
  locality TEXT,
  latitude NUMERIC(9,6) CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  longitude NUMERIC(9,6) CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
  map_url TEXT CHECK (map_url IS NULL OR map_url ~* '^https://'),
  directions TEXT,
  contact_phone TEXT,
  contact_email TEXT,
  whatsapp_number TEXT,
  check_in_time TIME,
  check_out_time TIME,
  max_stay_guests INTEGER CHECK (max_stay_guests IS NULL OR max_stay_guests > 0),
  max_event_guests INTEGER CHECK (max_event_guests IS NULL OR max_event_guests > 0),
  guest_policies TEXT,
  event_policies TEXT,
  cancellation_policy TEXT,
  refund_policy TEXT,
  food_info TEXT,
  activities_info TEXT,
  accessibility_info TEXT,
  parking_info TEXT,
  privacy_policy TEXT,
  terms TEXT,
  -- Booking logic assumes India's fixed +05:30 offset (no DST).
  timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata' CHECK (timezone = 'Asia/Kolkata'),
  currency TEXT NOT NULL DEFAULT 'INR' CHECK (currency = 'INR'),
  is_published BOOLEAN NOT NULL DEFAULT FALSE,
  bot_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  test_mode BOOLEAN NOT NULL DEFAULT TRUE,
  payments_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  -- When true a reservation is confirmed only by a staff member, even
  -- after a verified payment (the dates stay protected meanwhile).
  manual_approval_required BOOLEAN NOT NULL DEFAULT TRUE,
  holds_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  hold_duration_minutes INTEGER NOT NULL DEFAULT 30
    CHECK (hold_duration_minutes BETWEEN 5 AND 2880),
  -- Setup / cleanup time added around every event on the calendar.
  event_buffer_minutes INTEGER NOT NULL DEFAULT 0
    CHECK (event_buffer_minutes BETWEEN 0 AND 720),
  -- {"mon":{"open":"09:00","close":"20:00"}, ...}; NULL = not configured.
  business_hours JSONB,
  -- {"new_enquiry":true,"payment_verified":true,...}
  notification_settings JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- {"arrival_reminder_hours":24,"checkout_reminder_hours":2,
  --  "arrival_template":"<approved template name>", ...}
  reminder_settings JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- The public website serves exactly one published property.
CREATE UNIQUE INDEX IF NOT EXISTS uq_property_settings_one_published
  ON property_settings ((TRUE)) WHERE is_published;

-- ============================================================
-- PROPERTY MEDIA / AMENITIES / FAQS
-- ============================================================
CREATE TABLE IF NOT EXISTS property_media (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  storage_path TEXT,
  public_url TEXT NOT NULL CHECK (public_url ~* '^https?://'),
  caption TEXT,
  alt_text TEXT,
  category TEXT NOT NULL DEFAULT 'other'
    CHECK (category IN ('farm', 'building', 'rooms', 'event_space', 'amenities', 'food', 'other')),
  -- Only photographs confirmed to show V-Farms itself may be shown as such.
  is_verified_property_photo BOOLEAN NOT NULL DEFAULT FALSE,
  is_approved BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  uploaded_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_property_media_account ON property_media(account_id, sort_order);

CREATE TABLE IF NOT EXISTS amenities (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  description TEXT,
  applies_to TEXT NOT NULL DEFAULT 'both' CHECK (applies_to IN ('stay', 'event', 'both')),
  is_approved BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (account_id, name)
);

CREATE TABLE IF NOT EXISTS property_faqs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  question TEXT NOT NULL CHECK (length(trim(question)) > 0),
  answer TEXT NOT NULL CHECK (length(trim(answer)) > 0),
  is_published BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_property_faqs_account ON property_faqs(account_id, sort_order);

-- ============================================================
-- PRICING
-- ============================================================
-- One rule set per account. NULL rates = not configured → no quote.
CREATE TABLE IF NOT EXISTS pricing_rules (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL UNIQUE REFERENCES accounts(id) ON DELETE CASCADE,
  weekday_night_rate NUMERIC(12,2) CHECK (weekday_night_rate IS NULL OR weekday_night_rate >= 0),
  weekend_night_rate NUMERIC(12,2) CHECK (weekend_night_rate IS NULL OR weekend_night_rate >= 0),
  -- ISO weekday of the NIGHT's start date priced at the weekend rate
  -- (5 = Friday night, 6 = Saturday night).
  weekend_nights SMALLINT[] NOT NULL DEFAULT '{5,6}'
    CHECK (weekend_nights <@ ARRAY[1,2,3,4,5,6,7]::SMALLINT[]),
  base_guests_included INTEGER CHECK (base_guests_included IS NULL OR base_guests_included > 0),
  extra_adult_rate_per_night NUMERIC(12,2) CHECK (extra_adult_rate_per_night IS NULL OR extra_adult_rate_per_night >= 0),
  extra_child_rate_per_night NUMERIC(12,2) CHECK (extra_child_rate_per_night IS NULL OR extra_child_rate_per_night >= 0),
  -- Children strictly older than this are priced as adults.
  child_age_limit INTEGER CHECK (child_age_limit IS NULL OR child_age_limit BETWEEN 0 AND 17),
  min_nights INTEGER NOT NULL DEFAULT 1 CHECK (min_nights >= 1),
  extended_stay_min_nights INTEGER CHECK (extended_stay_min_nights IS NULL OR extended_stay_min_nights >= 2),
  extended_stay_discount_pct NUMERIC(5,2) CHECK (extended_stay_discount_pct IS NULL OR extended_stay_discount_pct BETWEEN 0 AND 100),
  tax_label TEXT NOT NULL DEFAULT 'GST',
  tax_pct NUMERIC(5,2) CHECK (tax_pct IS NULL OR tax_pct BETWEEN 0 AND 100),
  prices_include_tax BOOLEAN NOT NULL DEFAULT FALSE,
  deposit_pct NUMERIC(5,2) CHECK (deposit_pct IS NULL OR deposit_pct BETWEEN 0 AND 100),
  deposit_fixed_amount NUMERIC(12,2) CHECK (deposit_fixed_amount IS NULL OR deposit_fixed_amount >= 0),
  quote_validity_hours INTEGER CHECK (quote_validity_hours IS NULL OR quote_validity_hours > 0),
  -- Largest discount a staff member may authorise on a quote.
  max_staff_discount_pct NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK (max_staff_discount_pct BETWEEN 0 AND 100),
  -- [{"days_before":7,"refund_pct":100}, ...] — informational for staff.
  cancellation_rules JSONB,
  updated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT pricing_rules_one_deposit_kind CHECK (deposit_pct IS NULL OR deposit_fixed_amount IS NULL)
);

-- Seasonal / special-date overrides. Special dates and holidays (tier 2)
-- win over seasons (tier 1); rates of the same tier may not overlap, so
-- the nightly price is always deterministic.
CREATE TABLE IF NOT EXISTS seasonal_rates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  kind TEXT NOT NULL DEFAULT 'season' CHECK (kind IN ('season', 'special_date', 'holiday')),
  rate_tier SMALLINT GENERATED ALWAYS AS (CASE WHEN kind = 'season' THEN 1 ELSE 2 END) STORED,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  nightly_rate NUMERIC(12,2) NOT NULL CHECK (nightly_rate >= 0),
  weekend_nightly_rate NUMERIC(12,2) CHECK (weekend_nightly_rate IS NULL OR weekend_nightly_rate >= 0),
  min_nights INTEGER CHECK (min_nights IS NULL OR min_nights >= 1),
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT seasonal_rates_valid_range CHECK (end_date >= start_date)
);
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'seasonal_rates_no_overlap') THEN
    ALTER TABLE seasonal_rates ADD CONSTRAINT seasonal_rates_no_overlap
      EXCLUDE USING gist (
        account_id WITH =,
        rate_tier WITH =,
        daterange(start_date, end_date, '[]') WITH &&
      ) WHERE (is_active);
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS event_packages (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  description TEXT,
  -- NULL = applies to every event type.
  event_types TEXT[],
  base_price NUMERIC(12,2) NOT NULL CHECK (base_price >= 0),
  included_hours NUMERIC(4,1) CHECK (included_hours IS NULL OR included_hours > 0),
  extra_hour_rate NUMERIC(12,2) CHECK (extra_hour_rate IS NULL OR extra_hour_rate >= 0),
  max_guests INTEGER CHECK (max_guests IS NULL OR max_guests > 0),
  includes_accommodation BOOLEAN NOT NULL DEFAULT FALSE,
  is_active BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS addons (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  description TEXT,
  price NUMERIC(12,2) NOT NULL CHECK (price >= 0),
  unit TEXT NOT NULL DEFAULT 'per_booking'
    CHECK (unit IN ('per_booking', 'per_night', 'per_guest', 'per_guest_per_night')),
  applies_to TEXT NOT NULL DEFAULT 'both' CHECK (applies_to IN ('stay', 'event', 'both')),
  is_active BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ============================================================
-- LEADS
-- ============================================================
CREATE TABLE IF NOT EXISTS leads (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  lead_number BIGINT GENERATED ALWAYS AS IDENTITY,
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  contact_id UUID REFERENCES contacts(id) ON DELETE SET NULL,
  conversation_id UUID REFERENCES conversations(id) ON DELETE SET NULL,
  customer_name TEXT,
  -- E.164 digits with leading '+', e.g. +919876543210.
  phone_e164 TEXT CHECK (phone_e164 IS NULL OR phone_e164 ~ '^\+[1-9][0-9]{6,14}$'),
  email TEXT,
  preferred_language TEXT NOT NULL DEFAULT 'en',
  source TEXT NOT NULL DEFAULT 'whatsapp'
    CHECK (source IN ('website', 'whatsapp', 'qr_code', 'instagram', 'facebook_ads', 'referral', 'manual')),
  category TEXT NOT NULL DEFAULT 'general' CHECK (category IN ('stay', 'event', 'pricing', 'general')),
  stage TEXT NOT NULL DEFAULT 'new'
    CHECK (stage IN ('new', 'contacted', 'qualified', 'quote_sent', 'awaiting_customer',
                     'booking_requested', 'confirmed', 'completed', 'cancelled', 'lost')),
  priority TEXT NOT NULL DEFAULT 'nurture' CHECK (priority IN ('hot', 'warm', 'nurture')),
  check_in DATE,
  check_out DATE,
  event_date DATE,
  event_start_time TIME,
  event_end_time TIME,
  adults INTEGER CHECK (adults IS NULL OR adults >= 0),
  children INTEGER CHECK (children IS NULL OR children >= 0),
  children_ages INTEGER[],
  guest_count INTEGER CHECK (guest_count IS NULL OR guest_count >= 0),
  purpose TEXT,
  special_requirements TEXT,
  budget_inr NUMERIC(12,2) CHECK (budget_inr IS NULL OR budget_inr >= 0),
  estimated_quote_inr NUMERIC(12,2) CHECK (estimated_quote_inr IS NULL OR estimated_quote_inr >= 0),
  assigned_to UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  last_interaction_at TIMESTAMPTZ,
  next_follow_up_at TIMESTAMPTZ,
  notes TEXT,
  consent_status TEXT NOT NULL DEFAULT 'unknown' CHECK (consent_status IN ('unknown', 'granted', 'revoked')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT leads_valid_stay_dates CHECK (check_in IS NULL OR check_out IS NULL OR check_out > check_in)
);
-- One open lead per contact: repeat enquiries update it instead of
-- creating duplicates.
CREATE UNIQUE INDEX IF NOT EXISTS uq_leads_open_per_contact
  ON leads(account_id, contact_id)
  WHERE contact_id IS NOT NULL AND stage NOT IN ('completed', 'cancelled', 'lost');
CREATE INDEX IF NOT EXISTS idx_leads_account_stage ON leads(account_id, stage, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_leads_follow_up ON leads(account_id, next_follow_up_at)
  WHERE next_follow_up_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_leads_phone ON leads(account_id, phone_e164);

CREATE TABLE IF NOT EXISTS lead_notes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  lead_id UUID NOT NULL REFERENCES leads(id) ON DELETE CASCADE,
  author_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  body TEXT NOT NULL CHECK (length(trim(body)) > 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_lead_notes_lead ON lead_notes(lead_id, created_at DESC);

-- ============================================================
-- CONVERSATION STATE (resort bot)
-- ============================================================
CREATE TABLE IF NOT EXISTS conversation_states (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  conversation_id UUID NOT NULL UNIQUE REFERENCES conversations(id) ON DELETE CASCADE,
  contact_id UUID NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  lead_id UUID REFERENCES leads(id) ON DELETE SET NULL,
  flow TEXT NOT NULL DEFAULT 'menu',
  step TEXT NOT NULL DEFAULT 'start',
  data JSONB NOT NULL DEFAULT '{}'::jsonb,
  history JSONB NOT NULL DEFAULT '[]'::jsonb,
  language TEXT NOT NULL DEFAULT 'en',
  bot_mode TEXT NOT NULL DEFAULT 'bot' CHECK (bot_mode IN ('bot', 'human')),
  handoff_reason TEXT,
  handoff_at TIMESTAMPTZ,
  handed_off_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  resumed_at TIMESTAMPTZ,
  resumed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  last_inbound_at TIMESTAMPTZ,
  last_processed_message_id TEXT,
  version INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_conversation_states_account_mode
  ON conversation_states(account_id, bot_mode);

-- ============================================================
-- BOOKINGS
-- ============================================================
CREATE TABLE IF NOT EXISTS bookings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  booking_ref TEXT NOT NULL UNIQUE,
  lead_id UUID REFERENCES leads(id) ON DELETE SET NULL,
  contact_id UUID REFERENCES contacts(id) ON DELETE SET NULL,
  conversation_id UUID REFERENCES conversations(id) ON DELETE SET NULL,
  booking_type TEXT NOT NULL CHECK (booking_type IN ('stay', 'event')),
  status TEXT NOT NULL DEFAULT 'enquiry'
    CHECK (status IN ('enquiry', 'qualified', 'availability_checked', 'quote_created',
                      'booking_requested', 'hold', 'payment_pending', 'payment_verified',
                      'confirmed', 'checked_in', 'checked_out', 'completed',
                      'cancellation_requested', 'cancelled', 'rejected', 'expired')),
  source TEXT NOT NULL DEFAULT 'whatsapp'
    CHECK (source IN ('website', 'whatsapp', 'qr_code', 'instagram', 'facebook_ads', 'referral', 'manual')),
  check_in DATE,
  check_out DATE,
  event_date DATE,
  event_start_time TIME,
  event_end_time TIME,
  adults INTEGER NOT NULL DEFAULT 0 CHECK (adults >= 0),
  children INTEGER NOT NULL DEFAULT 0 CHECK (children >= 0),
  children_ages INTEGER[],
  guest_count INTEGER NOT NULL CHECK (guest_count >= 1),
  purpose TEXT,
  special_requirements TEXT,
  guest_name TEXT,
  guest_phone TEXT CHECK (guest_phone IS NULL OR guest_phone ~ '^\+[1-9][0-9]{6,14}$'),
  guest_email TEXT,
  active_quote_id UUID,
  quoted_total NUMERIC(12,2) CHECK (quoted_total IS NULL OR quoted_total >= 0),
  advance_due NUMERIC(12,2) CHECK (advance_due IS NULL OR advance_due >= 0),
  amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (amount_paid >= 0),
  amount_refunded NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (amount_refunded >= 0),
  payment_status TEXT NOT NULL DEFAULT 'unpaid'
    CHECK (payment_status IN ('unpaid', 'partially_paid', 'paid', 'refund_pending',
                              'partially_refunded', 'refunded')),
  -- Set when money was verified but the dates could no longer be
  -- reserved (hold expired and someone else booked). Staff must act.
  availability_conflict BOOLEAN NOT NULL DEFAULT FALSE,
  -- SHA-256 of the guest's private booking link token.
  access_token_hash TEXT,
  idempotency_key TEXT,
  staff_notes TEXT,
  confirmed_at TIMESTAMPTZ,
  confirmed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  cancelled_at TIMESTAMPTZ,
  cancellation_reason TEXT,
  completed_at TIMESTAMPTZ,
  created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT bookings_type_fields CHECK (
    (booking_type = 'stay' AND check_in IS NOT NULL AND check_out IS NOT NULL AND check_out > check_in)
    OR
    (booking_type = 'event' AND event_date IS NOT NULL AND event_start_time IS NOT NULL
      AND event_end_time IS NOT NULL AND event_end_time <> event_start_time)
  ),
  CONSTRAINT bookings_guest_split CHECK (guest_count >= adults + children OR booking_type = 'event'),
  CONSTRAINT bookings_idempotency UNIQUE (account_id, idempotency_key)
);
CREATE INDEX IF NOT EXISTS idx_bookings_account_status ON bookings(account_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_bookings_account_check_in ON bookings(account_id, check_in);
CREATE INDEX IF NOT EXISTS idx_bookings_account_event_date ON bookings(account_id, event_date);
CREATE INDEX IF NOT EXISTS idx_bookings_lead ON bookings(lead_id);

CREATE TABLE IF NOT EXISTS booking_guests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  full_name TEXT,
  age INTEGER CHECK (age IS NULL OR age BETWEEN 0 AND 120),
  is_child BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_booking_guests_booking ON booking_guests(booking_id);

CREATE TABLE IF NOT EXISTS booking_quotes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  booking_id UUID REFERENCES bookings(id) ON DELETE CASCADE,
  lead_id UUID REFERENCES leads(id) ON DELETE SET NULL,
  booking_type TEXT NOT NULL CHECK (booking_type IN ('stay', 'event')),
  line_items JSONB NOT NULL DEFAULT '[]'::jsonb,
  nights INTEGER CHECK (nights IS NULL OR nights > 0),
  event_hours NUMERIC(5,2) CHECK (event_hours IS NULL OR event_hours > 0),
  subtotal NUMERIC(12,2) NOT NULL CHECK (subtotal >= 0),
  discount_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
  discount_reason TEXT,
  discount_authorized_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  tax_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
  total_amount NUMERIC(12,2) NOT NULL CHECK (total_amount >= 0),
  advance_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (advance_amount >= 0),
  balance_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (balance_amount >= 0),
  currency TEXT NOT NULL DEFAULT 'INR' CHECK (currency = 'INR'),
  valid_until TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'sent', 'accepted', 'expired', 'superseded')),
  pricing_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT booking_quotes_discount_needs_authoriser
    CHECK (discount_amount = 0 OR discount_authorized_by IS NOT NULL),
  CONSTRAINT booking_quotes_advance_within_total CHECK (advance_amount <= total_amount)
);
CREATE INDEX IF NOT EXISTS idx_booking_quotes_booking ON booking_quotes(booking_id, created_at DESC);

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'bookings_active_quote_fk') THEN
    ALTER TABLE bookings ADD CONSTRAINT bookings_active_quote_fk
      FOREIGN KEY (active_quote_id) REFERENCES booking_quotes(id) ON DELETE SET NULL;
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS event_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  booking_id UUID NOT NULL UNIQUE REFERENCES bookings(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL
    CHECK (event_type IN ('birthday', 'anniversary', 'family_gathering', 'private_celebration', 'corporate', 'other')),
  event_type_other TEXT,
  accommodation_required BOOLEAN,
  catering_required BOOLEAN,
  decoration_requirements TEXT,
  budget_inr NUMERIC(12,2) CHECK (budget_inr IS NULL OR budget_inr >= 0),
  contact_phone TEXT,
  contact_email TEXT,
  status TEXT NOT NULL DEFAULT 'pending_review'
    CHECK (status IN ('pending_review', 'approved', 'rejected', 'cancelled')),
  review_notes TEXT,
  reviewed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  reviewed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_event_requests_status ON event_requests(account_id, status);

-- ============================================================
-- AVAILABILITY (the single-estate calendar)
-- ============================================================
CREATE TABLE IF NOT EXISTS availability_blocks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  period TSTZRANGE NOT NULL,
  block_type TEXT NOT NULL CHECK (block_type IN ('booking', 'hold', 'manual_block', 'maintenance')),
  booking_id UUID REFERENCES bookings(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'released', 'expired')),
  expires_at TIMESTAMPTZ,
  reason TEXT,
  created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  released_at TIMESTAMPTZ,
  CONSTRAINT availability_blocks_nonempty CHECK (NOT isempty(period) AND lower(period) < upper(period)),
  CONSTRAINT availability_blocks_hold_expires CHECK (block_type <> 'hold' OR expires_at IS NOT NULL),
  CONSTRAINT availability_blocks_booking_link CHECK (block_type NOT IN ('booking', 'hold') OR booking_id IS NOT NULL)
);
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'availability_blocks_no_overlap') THEN
    ALTER TABLE availability_blocks ADD CONSTRAINT availability_blocks_no_overlap
      EXCLUDE USING gist (account_id WITH =, period WITH &&) WHERE (status = 'active');
  END IF;
END $$;
CREATE UNIQUE INDEX IF NOT EXISTS uq_availability_blocks_one_active_per_booking
  ON availability_blocks(booking_id) WHERE status = 'active' AND booking_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_availability_blocks_holds
  ON availability_blocks(account_id, expires_at) WHERE status = 'active' AND block_type = 'hold';

-- ============================================================
-- PAYMENTS / REFUNDS
-- ============================================================
CREATE TABLE IF NOT EXISTS payments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT,
  provider TEXT NOT NULL CHECK (provider IN ('razorpay', 'manual')),
  purpose TEXT NOT NULL DEFAULT 'advance' CHECK (purpose IN ('advance', 'balance', 'full')),
  amount_paise BIGINT NOT NULL CHECK (amount_paise > 0),
  amount_refunded_paise BIGINT NOT NULL DEFAULT 0 CHECK (amount_refunded_paise >= 0),
  currency TEXT NOT NULL DEFAULT 'INR' CHECK (currency = 'INR'),
  provider_order_id TEXT UNIQUE,
  provider_payment_id TEXT UNIQUE,
  status TEXT NOT NULL DEFAULT 'created'
    CHECK (status IN ('created', 'attempted', 'captured', 'failed', 'refunded', 'partially_refunded')),
  method TEXT,
  failure_code TEXT,
  failure_reason TEXT,
  verified_via TEXT CHECK (verified_via IS NULL OR verified_via IN ('checkout_signature', 'webhook', 'manual')),
  verified_at TIMESTAMPTZ,
  recorded_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT payments_refund_within_amount CHECK (amount_refunded_paise <= amount_paise),
  CONSTRAINT payments_razorpay_has_order CHECK (provider <> 'razorpay' OR provider_order_id IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_payments_booking ON payments(booking_id, created_at DESC);

CREATE TABLE IF NOT EXISTS refunds (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  payment_id UUID NOT NULL REFERENCES payments(id) ON DELETE RESTRICT,
  booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT,
  amount_paise BIGINT NOT NULL CHECK (amount_paise > 0),
  provider_refund_id TEXT UNIQUE,
  -- processed       : the provider confirmed the refund
  -- manual_recorded : an authorised operator recorded an offline refund
  status TEXT NOT NULL DEFAULT 'requested'
    CHECK (status IN ('requested', 'pending', 'processed', 'failed', 'manual_recorded')),
  reason TEXT,
  notes TEXT,
  requested_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  processed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_refunds_booking ON refunds(booking_id);

-- ============================================================
-- NOTIFICATION JOBS
-- ============================================================
CREATE TABLE IF NOT EXISTS notification_jobs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN (
    'new_enquiry', 'qualified_lead', 'quote_requested', 'booking_requested',
    'payment_verified', 'booking_confirmed', 'upcoming_arrival', 'upcoming_checkout',
    'event_approval_required', 'cancellation_requested', 'message_failed', 'handoff_requested'
  )),
  -- staff    : in-app notification for team members
  -- whatsapp : message to the guest (session window or approved template)
  channel TEXT NOT NULL CHECK (channel IN ('staff', 'whatsapp')),
  contact_id UUID REFERENCES contacts(id) ON DELETE CASCADE,
  conversation_id UUID REFERENCES conversations(id) ON DELETE CASCADE,
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  booking_id UUID REFERENCES bookings(id) ON DELETE CASCADE,
  lead_id UUID REFERENCES leads(id) ON DELETE CASCADE,
  template_name TEXT,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  scheduled_for TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'processing', 'sent', 'failed', 'cancelled', 'skipped')),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  max_attempts INTEGER NOT NULL DEFAULT 3 CHECK (max_attempts BETWEEN 1 AND 10),
  last_error TEXT,
  dedupe_key TEXT,
  locked_at TIMESTAMPTZ,
  sent_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT notification_jobs_dedupe UNIQUE (account_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_notification_jobs_due
  ON notification_jobs(scheduled_for) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS idx_notification_jobs_booking ON notification_jobs(booking_id);

-- Staff alerts reuse the existing in-app notifications table.
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS link_path TEXT;
ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_type_check;
ALTER TABLE notifications ADD CONSTRAINT notifications_type_check
  CHECK (type IN ('conversation_assigned', 'resort_alert'));

-- ============================================================
-- AUDIT / WEBHOOK EVENTS / CONSENT
-- ============================================================
CREATE TABLE IF NOT EXISTS audit_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID REFERENCES accounts(id) ON DELETE CASCADE,
  actor_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  actor_type TEXT NOT NULL DEFAULT 'user' CHECK (actor_type IN ('user', 'system', 'bot', 'webhook')),
  action TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id UUID,
  before JSONB,
  after JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_audit_logs_account ON audit_logs(account_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_logs_entity ON audit_logs(entity_type, entity_id);

CREATE TABLE IF NOT EXISTS webhook_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  provider TEXT NOT NULL CHECK (provider IN ('razorpay', 'whatsapp')),
  event_id TEXT NOT NULL,
  event_type TEXT,
  account_id UUID REFERENCES accounts(id) ON DELETE SET NULL,
  payload_sha256 TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'received' CHECK (status IN ('received', 'processed', 'ignored', 'failed')),
  error TEXT,
  received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  processed_at TIMESTAMPTZ,
  CONSTRAINT webhook_events_unique UNIQUE (provider, event_id)
);

CREATE TABLE IF NOT EXISTS consent_records (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  contact_id UUID REFERENCES contacts(id) ON DELETE SET NULL,
  phone_e164 TEXT,
  channel TEXT NOT NULL DEFAULT 'whatsapp' CHECK (channel IN ('whatsapp')),
  consent_type TEXT NOT NULL CHECK (consent_type IN ('service', 'marketing')),
  status TEXT NOT NULL CHECK (status IN ('granted', 'revoked')),
  source TEXT NOT NULL CHECK (source IN ('whatsapp_inbound', 'website_form', 'stop_keyword', 'start_keyword', 'staff')),
  evidence TEXT,
  recorded_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_consent_records_contact ON consent_records(account_id, contact_id, created_at DESC);

-- ============================================================
-- updated_at triggers
-- ============================================================
DO $$
DECLARE
  v_table TEXT;
BEGIN
  FOREACH v_table IN ARRAY ARRAY[
    'property_settings', 'property_media', 'amenities', 'property_faqs',
    'pricing_rules', 'seasonal_rates', 'event_packages', 'addons',
    'leads', 'conversation_states', 'bookings', 'event_requests',
    'payments', 'refunds', 'notification_jobs'
  ] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS set_updated_at ON %I', v_table);
    EXECUTE format(
      'CREATE TRIGGER set_updated_at BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()',
      v_table
    );
  END LOOP;
END $$;

-- ============================================================
-- ROW LEVEL SECURITY
--
-- No anon policies anywhere: the public website reads published,
-- approved rows through server routes with the service role, never
-- straight from the browser.
-- ============================================================
DO $$
DECLARE
  v_table TEXT;
BEGIN
  -- Settings-class: members read, admins write.
  FOREACH v_table IN ARRAY ARRAY[
    'property_settings', 'property_media', 'amenities', 'property_faqs',
    'pricing_rules', 'seasonal_rates', 'event_packages', 'addons'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', v_table);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_table || '_select', v_table);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_table || '_insert', v_table);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_table || '_update', v_table);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_table || '_delete', v_table);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (is_account_member(account_id))', v_table || '_select', v_table);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (is_account_member(account_id, ''admin''))', v_table || '_insert', v_table);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (is_account_member(account_id, ''admin'')) WITH CHECK (is_account_member(account_id, ''admin''))', v_table || '_update', v_table);
    EXECUTE format('CREATE POLICY %I ON %I FOR DELETE USING (is_account_member(account_id, ''admin''))', v_table || '_delete', v_table);
  END LOOP;

  -- Operational: members read, agents (reservation managers) write,
  -- admins delete.
  FOREACH v_table IN ARRAY ARRAY[
    'leads', 'lead_notes', 'conversation_states', 'bookings', 'booking_guests',
    'booking_quotes', 'event_requests'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', v_table);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_table || '_select', v_table);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_table || '_insert', v_table);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_table || '_update', v_table);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_table || '_delete', v_table);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (is_account_member(account_id))', v_table || '_select', v_table);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (is_account_member(account_id, ''agent''))', v_table || '_insert', v_table);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (is_account_member(account_id, ''agent'')) WITH CHECK (is_account_member(account_id, ''agent''))', v_table || '_update', v_table);
    EXECUTE format('CREATE POLICY %I ON %I FOR DELETE USING (is_account_member(account_id, ''admin''))', v_table || '_delete', v_table);
  END LOOP;

  -- Server-written ledgers: members read; writes only through the
  -- service role / SECURITY DEFINER functions.
  FOREACH v_table IN ARRAY ARRAY[
    'availability_blocks', 'payments', 'refunds', 'consent_records'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', v_table);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_table || '_select', v_table);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (is_account_member(account_id))', v_table || '_select', v_table);
  END LOOP;
END $$;

-- Pricing must not be readable by guests (no anon policy); notification
-- jobs are visible to reservation managers, audit + webhook logs to admins.
ALTER TABLE notification_jobs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS notification_jobs_select ON notification_jobs;
CREATE POLICY notification_jobs_select ON notification_jobs FOR SELECT
  USING (is_account_member(account_id, 'agent'));

ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS audit_logs_select ON audit_logs;
CREATE POLICY audit_logs_select ON audit_logs FOR SELECT
  USING (account_id IS NOT NULL AND is_account_member(account_id, 'admin'));

ALTER TABLE webhook_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS webhook_events_select ON webhook_events;
CREATE POLICY webhook_events_select ON webhook_events FOR SELECT
  USING (account_id IS NOT NULL AND is_account_member(account_id, 'admin'));

-- Ledgers are append/modify by the server only, even for members who
-- could otherwise write through PostgREST grants.
REVOKE INSERT, UPDATE, DELETE ON availability_blocks, payments, refunds, consent_records,
  notification_jobs, audit_logs, webhook_events FROM anon, authenticated;

-- Realtime for the dashboard's live booking / conversation-state views.
DO $$
DECLARE
  v_table TEXT;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    FOREACH v_table IN ARRAY ARRAY['bookings', 'conversation_states', 'leads'] LOOP
      IF NOT EXISTS (
        SELECT 1 FROM pg_publication_tables
        WHERE pubname = 'supabase_realtime' AND tablename = v_table
      ) THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE %I', v_table);
      END IF;
    END LOOP;
  END IF;
END $$;

-- >>>>>>>>>> 060_vfarms_resort_functions.sql
-- ============================================================
-- V-Farms reservation functions.
--
-- Concurrency model
--   * Every write to the estate calendar goes through these functions.
--   * Each takes a transaction-scoped advisory lock keyed on the account,
--     so reservations for the estate are serialised; the exclusion
--     constraint availability_blocks_no_overlap is the final guarantee.
--   * Expired holds are released inside the same transaction before a
--     new block is inserted, so a stale hold never blocks a new guest
--     and is never silently extended.
--
-- Time zone
--   bookings.occupancy is a tstzrange computed by the application from
--   the IST (+05:30, no DST) dates and configured times. Stays are
--   [check_in + check_in_time, check_out + check_out_time); when those
--   times are not configured 12:00 IST is used for the calendar only.
--   Events are [date + start - buffer, date + end + buffer), with an end
--   at or before the start meaning the event runs past midnight.
--
-- All functions are SECURITY DEFINER and executable by service_role
-- only; API routes enforce the caller's role before calling them.
-- Idempotent — safe to run multiple times.
-- ============================================================

ALTER TABLE bookings ADD COLUMN IF NOT EXISTS occupancy TSTZRANGE;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'bookings_occupancy_nonempty') THEN
    ALTER TABLE bookings ADD CONSTRAINT bookings_occupancy_nonempty
      CHECK (occupancy IS NULL OR (NOT isempty(occupancy) AND lower(occupancy) < upper(occupancy)));
  END IF;
END $$;

-- ------------------------------------------------------------
-- Advisory lock helper
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_lock_estate(p_account UUID)
RETURNS VOID
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT pg_advisory_xact_lock(hashtextextended('vfarms-estate:' || p_account::text, 0));
$$;

-- ------------------------------------------------------------
-- Release holds whose expiry has passed. Bookings left in hold /
-- payment_pending with no money received become 'expired'.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_expire_stale_holds(p_account UUID)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count INTEGER;
BEGIN
  WITH expired AS (
    UPDATE availability_blocks
       SET status = 'expired', released_at = NOW()
     WHERE account_id = p_account
       AND status = 'active'
       AND block_type = 'hold'
       AND expires_at <= NOW()
    RETURNING booking_id
  )
  UPDATE bookings b
     SET status = 'expired'
    FROM expired e
   WHERE b.id = e.booking_id
     AND b.status IN ('hold', 'payment_pending')
     AND b.amount_paid = 0;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- ------------------------------------------------------------
-- Blocks that overlap [p_start, p_end). Expired holds are ignored even
-- before the sweep has released them.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_find_conflicts(
  p_account UUID,
  p_start TIMESTAMPTZ,
  p_end TIMESTAMPTZ,
  p_exclude_booking UUID DEFAULT NULL
)
RETURNS TABLE (
  block_id UUID,
  block_type TEXT,
  booking_id UUID,
  starts_at TIMESTAMPTZ,
  ends_at TIMESTAMPTZ
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT a.id, a.block_type, a.booking_id, lower(a.period), upper(a.period)
    FROM availability_blocks a
   WHERE a.account_id = p_account
     AND a.status = 'active'
     AND NOT (a.block_type = 'hold' AND a.expires_at <= NOW())
     AND a.period && tstzrange(p_start, p_end, '[)')
     AND (p_exclude_booking IS NULL OR a.booking_id IS DISTINCT FROM p_exclude_booking)
   ORDER BY lower(a.period);
$$;

-- ------------------------------------------------------------
-- Occupy the calendar for a booking (hold or firm booking) or add a
-- manual / maintenance block. Replaces the booking's previous active
-- block atomically (hold → booking, reschedule). Raises SQLSTATE 23P01
-- with message 'estate_unavailable' when the dates are taken.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_reserve(
  p_account UUID,
  p_block_type TEXT,
  p_booking UUID DEFAULT NULL,
  p_start TIMESTAMPTZ DEFAULT NULL,
  p_end TIMESTAMPTZ DEFAULT NULL,
  p_expires_at TIMESTAMPTZ DEFAULT NULL,
  p_reason TEXT DEFAULT NULL,
  p_actor UUID DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_period TSTZRANGE;
  v_block UUID;
  v_booking bookings%ROWTYPE;
BEGIN
  IF p_block_type NOT IN ('booking', 'hold', 'manual_block', 'maintenance') THEN
    RAISE EXCEPTION 'invalid_block_type' USING ERRCODE = '22023';
  END IF;

  PERFORM resort_lock_estate(p_account);
  PERFORM resort_expire_stale_holds(p_account);

  IF p_booking IS NOT NULL THEN
    SELECT * INTO v_booking FROM bookings
     WHERE id = p_booking AND account_id = p_account
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'booking_not_found' USING ERRCODE = 'P0002';
    END IF;
    v_period := COALESCE(
      CASE WHEN p_start IS NOT NULL AND p_end IS NOT NULL THEN tstzrange(p_start, p_end, '[)') END,
      v_booking.occupancy
    );
  ELSE
    IF p_block_type IN ('booking', 'hold') THEN
      RAISE EXCEPTION 'booking_required' USING ERRCODE = '22023';
    END IF;
    v_period := tstzrange(p_start, p_end, '[)');
  END IF;

  IF v_period IS NULL OR isempty(v_period) THEN
    RAISE EXCEPTION 'invalid_period' USING ERRCODE = '22023';
  END IF;
  IF p_block_type = 'hold' AND (p_expires_at IS NULL OR p_expires_at <= NOW()) THEN
    RAISE EXCEPTION 'hold_requires_future_expiry' USING ERRCODE = '22023';
  END IF;

  IF p_booking IS NOT NULL THEN
    UPDATE availability_blocks
       SET status = 'released', released_at = NOW()
     WHERE booking_id = p_booking AND status = 'active';
  END IF;

  BEGIN
    INSERT INTO availability_blocks (account_id, period, block_type, booking_id, expires_at, reason, created_by)
    VALUES (
      p_account, v_period, p_block_type, p_booking,
      CASE WHEN p_block_type = 'hold' THEN p_expires_at END,
      p_reason, p_actor
    )
    RETURNING id INTO v_block;
  EXCEPTION WHEN exclusion_violation THEN
    RAISE EXCEPTION 'estate_unavailable' USING ERRCODE = '23P01';
  END;

  IF p_booking IS NOT NULL AND (v_booking.occupancy IS DISTINCT FROM v_period) THEN
    UPDATE bookings SET occupancy = v_period WHERE id = p_booking;
  END IF;

  RETURN v_block;
END;
$$;

-- ------------------------------------------------------------
-- Free the calendar for a booking (cancel / reject / reschedule-away).
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_release_booking(p_account UUID, p_booking UUID)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count INTEGER;
BEGIN
  PERFORM resort_lock_estate(p_account);
  UPDATE availability_blocks
     SET status = 'released', released_at = NOW()
   WHERE account_id = p_account AND booking_id = p_booking AND status = 'active';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- ------------------------------------------------------------
-- Re-derive a booking's money columns from the payment / refund ledger.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_recompute_booking_money(p_booking UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_paid NUMERIC(12,2);
  v_refunded NUMERIC(12,2);
  v_refund_pending BOOLEAN;
  v_total NUMERIC(12,2);
  v_status TEXT;
BEGIN
  SELECT COALESCE(SUM(amount_paise) FILTER (WHERE status IN ('captured', 'refunded', 'partially_refunded')), 0) / 100.0
    INTO v_paid
    FROM payments WHERE booking_id = p_booking;

  SELECT COALESCE(SUM(amount_paise) FILTER (WHERE status IN ('processed', 'manual_recorded')), 0) / 100.0,
         COALESCE(BOOL_OR(status IN ('requested', 'pending')), FALSE)
    INTO v_refunded, v_refund_pending
    FROM refunds WHERE booking_id = p_booking;

  SELECT quoted_total INTO v_total FROM bookings WHERE id = p_booking;

  v_status := CASE
    WHEN v_refund_pending THEN 'refund_pending'
    WHEN v_refunded > 0 AND v_refunded >= v_paid THEN 'refunded'
    WHEN v_refunded > 0 THEN 'partially_refunded'
    WHEN v_paid = 0 THEN 'unpaid'
    WHEN v_total IS NOT NULL AND v_paid >= v_total THEN 'paid'
    ELSE 'partially_paid'
  END;

  UPDATE bookings
     SET amount_paid = v_paid,
         amount_refunded = v_refunded,
         payment_status = v_status
   WHERE id = p_booking;
END;
$$;

-- ------------------------------------------------------------
-- Apply a payment whose authenticity the server has verified (checkout
-- signature or webhook signature). Idempotent per provider payment id.
--
-- The payment never bypasses availability: the booking's dates are
-- secured (hold converted, or re-reserved if the hold lapsed). If they
-- can no longer be secured the money is recorded, the booking is marked
-- availability_conflict and left for staff (refund or reschedule).
-- Confirmation happens here only when manual approval is disabled.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_apply_verified_payment(
  p_provider_order_id TEXT,
  p_provider_payment_id TEXT,
  p_amount_paise BIGINT,
  p_via TEXT,
  p_method TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_payment payments%ROWTYPE;
  v_booking bookings%ROWTYPE;
  v_manual BOOLEAN;
  v_block availability_blocks%ROWTYPE;
  v_conflict BOOLEAN := FALSE;
  v_new_status TEXT;
BEGIN
  IF p_via NOT IN ('checkout_signature', 'webhook') THEN
    RAISE EXCEPTION 'invalid_verification_source' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_payment FROM payments
   WHERE provider = 'razorpay' AND provider_order_id = p_provider_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_payment.status IN ('captured', 'refunded', 'partially_refunded') THEN
    IF v_payment.provider_payment_id IS DISTINCT FROM p_provider_payment_id THEN
      -- A second, different payment against an already-paid order.
      RAISE EXCEPTION 'order_already_paid_by_other_payment' USING ERRCODE = '23505';
    END IF;
    SELECT * INTO v_booking FROM bookings WHERE id = v_payment.booking_id;
    RETURN jsonb_build_object(
      'already_processed', TRUE,
      'booking_id', v_booking.id,
      'booking_status', v_booking.status,
      'availability_conflict', v_booking.availability_conflict
    );
  END IF;

  IF p_amount_paise <> v_payment.amount_paise THEN
    RAISE EXCEPTION 'amount_mismatch' USING ERRCODE = '22023';
  END IF;

  PERFORM resort_lock_estate(v_payment.account_id);

  UPDATE payments
     SET status = 'captured',
         provider_payment_id = p_provider_payment_id,
         verified_via = p_via,
         verified_at = NOW(),
         method = COALESCE(p_method, method),
         failure_code = NULL,
         failure_reason = NULL
   WHERE id = v_payment.id;

  SELECT * INTO v_booking FROM bookings WHERE id = v_payment.booking_id FOR UPDATE;
  PERFORM resort_recompute_booking_money(v_booking.id);

  SELECT COALESCE(manual_approval_required, TRUE) INTO v_manual
    FROM property_settings WHERE account_id = v_booking.account_id;
  v_manual := COALESCE(v_manual, TRUE);

  IF v_booking.status IN ('confirmed', 'checked_in', 'checked_out', 'completed') THEN
    -- Balance payment on an already-confirmed reservation.
    v_new_status := v_booking.status;
  ELSIF v_booking.status IN ('cancelled', 'rejected', 'cancellation_requested') THEN
    -- Money arrived for a booking that is no longer going ahead.
    v_conflict := TRUE;
    v_new_status := v_booking.status;
  ELSE
    PERFORM resort_expire_stale_holds(v_booking.account_id);
    SELECT * INTO v_block FROM availability_blocks
     WHERE booking_id = v_booking.id AND status = 'active'
     FOR UPDATE;

    IF FOUND THEN
      UPDATE availability_blocks
         SET block_type = 'booking', expires_at = NULL
       WHERE id = v_block.id;
    ELSIF v_booking.occupancy IS NULL THEN
      v_conflict := TRUE;
    ELSE
      BEGIN
        INSERT INTO availability_blocks (account_id, period, block_type, booking_id, reason)
        VALUES (v_booking.account_id, v_booking.occupancy, 'booking', v_booking.id, 'payment_verified');
      EXCEPTION WHEN exclusion_violation THEN
        v_conflict := TRUE;
      END;
    END IF;

    IF v_conflict OR v_manual OR v_booking.booking_type = 'event' THEN
      v_new_status := 'payment_verified';
    ELSE
      v_new_status := 'confirmed';
    END IF;
  END IF;

  UPDATE bookings
     SET status = v_new_status,
         availability_conflict = availability_conflict OR v_conflict,
         confirmed_at = CASE WHEN v_new_status = 'confirmed' AND confirmed_at IS NULL THEN NOW() ELSE confirmed_at END
   WHERE id = v_booking.id;

  IF v_new_status = 'confirmed' AND v_booking.lead_id IS NOT NULL THEN
    UPDATE leads SET stage = 'confirmed' WHERE id = v_booking.lead_id
      AND stage NOT IN ('completed', 'cancelled', 'lost');
  END IF;

  INSERT INTO audit_logs (account_id, actor_type, action, entity_type, entity_id, after)
  VALUES (v_booking.account_id, 'webhook', 'payment.verified', 'booking', v_booking.id,
          jsonb_build_object('payment_id', v_payment.id, 'via', p_via,
                             'status', v_new_status, 'availability_conflict', v_conflict));

  RETURN jsonb_build_object(
    'already_processed', FALSE,
    'booking_id', v_booking.id,
    'booking_status', v_new_status,
    'availability_conflict', v_conflict
  );
END;
$$;

-- ------------------------------------------------------------
-- Staff confirmation (manual approval workflow). Secures the dates and
-- confirms. Events must be approved first.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_confirm_booking(
  p_account UUID,
  p_booking UUID,
  p_actor UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_booking bookings%ROWTYPE;
  v_block availability_blocks%ROWTYPE;
  v_event_status TEXT;
BEGIN
  PERFORM resort_lock_estate(p_account);
  PERFORM resort_expire_stale_holds(p_account);

  SELECT * INTO v_booking FROM bookings
   WHERE id = p_booking AND account_id = p_account
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.status = 'confirmed' THEN
    RETURN jsonb_build_object('booking_id', v_booking.id, 'booking_status', 'confirmed', 'already_confirmed', TRUE);
  END IF;
  IF v_booking.status NOT IN ('enquiry', 'qualified', 'availability_checked', 'quote_created',
                              'booking_requested', 'hold', 'payment_pending', 'payment_verified', 'expired') THEN
    RAISE EXCEPTION 'invalid_transition' USING ERRCODE = '22023',
      DETAIL = format('cannot confirm a booking in status %s', v_booking.status);
  END IF;
  IF v_booking.occupancy IS NULL THEN
    RAISE EXCEPTION 'occupancy_missing' USING ERRCODE = '22023';
  END IF;
  IF v_booking.booking_type = 'event' THEN
    SELECT status INTO v_event_status FROM event_requests WHERE booking_id = v_booking.id;
    IF v_event_status IS DISTINCT FROM 'approved' THEN
      RAISE EXCEPTION 'event_not_approved' USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT * INTO v_block FROM availability_blocks
   WHERE booking_id = v_booking.id AND status = 'active'
   FOR UPDATE;
  IF FOUND AND v_block.period = v_booking.occupancy THEN
    UPDATE availability_blocks SET block_type = 'booking', expires_at = NULL WHERE id = v_block.id;
  ELSE
    IF FOUND THEN
      UPDATE availability_blocks SET status = 'released', released_at = NOW() WHERE id = v_block.id;
    END IF;
    BEGIN
      INSERT INTO availability_blocks (account_id, period, block_type, booking_id, reason, created_by)
      VALUES (p_account, v_booking.occupancy, 'booking', v_booking.id, 'staff_confirmed', p_actor);
    EXCEPTION WHEN exclusion_violation THEN
      RAISE EXCEPTION 'estate_unavailable' USING ERRCODE = '23P01';
    END;
  END IF;

  UPDATE bookings
     SET status = 'confirmed',
         availability_conflict = FALSE,
         confirmed_at = NOW(),
         confirmed_by = p_actor
   WHERE id = v_booking.id;

  IF v_booking.lead_id IS NOT NULL THEN
    UPDATE leads SET stage = 'confirmed' WHERE id = v_booking.lead_id
      AND stage NOT IN ('completed', 'cancelled', 'lost');
  END IF;

  INSERT INTO audit_logs (account_id, actor_user_id, actor_type, action, entity_type, entity_id, before, after)
  VALUES (p_account, p_actor, 'user', 'booking.confirmed', 'booking', v_booking.id,
          jsonb_build_object('status', v_booking.status),
          jsonb_build_object('status', 'confirmed'));

  RETURN jsonb_build_object('booking_id', v_booking.id, 'booking_status', 'confirmed', 'already_confirmed', FALSE);
END;
$$;

-- ------------------------------------------------------------
-- Claim due notification jobs (SKIP LOCKED so parallel cron runs never
-- double-send). Jobs stuck in 'processing' for 10 minutes are reclaimed.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_claim_notification_jobs(p_limit INTEGER DEFAULT 25)
RETURNS SETOF notification_jobs
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  WITH due AS (
    SELECT id FROM notification_jobs
     WHERE (status = 'pending' AND scheduled_for <= NOW())
        OR (status = 'processing' AND locked_at < NOW() - INTERVAL '10 minutes')
     ORDER BY scheduled_for
     LIMIT GREATEST(1, LEAST(p_limit, 100))
     FOR UPDATE SKIP LOCKED
  )
  UPDATE notification_jobs j
     SET status = 'processing', locked_at = NOW(), attempts = j.attempts + 1
    FROM due
   WHERE j.id = due.id
  RETURNING j.*;
END;
$$;

-- ------------------------------------------------------------
-- Audit trail for property, pricing and calendar-affecting settings.
-- auth.uid() is the signed-in admin when the change comes through the
-- dashboard's RLS-scoped client.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resort_audit_row_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_account UUID;
  v_id UUID;
BEGIN
  v_account := COALESCE(NEW.account_id, OLD.account_id);
  v_id := COALESCE(NEW.id, OLD.id);
  INSERT INTO audit_logs (account_id, actor_user_id, actor_type, action, entity_type, entity_id, before, after)
  VALUES (
    v_account,
    auth.uid(),
    CASE WHEN auth.uid() IS NULL THEN 'system' ELSE 'user' END,
    lower(TG_OP),
    TG_TABLE_NAME,
    v_id,
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) END
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;

DO $$
DECLARE
  v_table TEXT;
BEGIN
  FOREACH v_table IN ARRAY ARRAY[
    'pricing_rules', 'seasonal_rates', 'event_packages', 'addons', 'property_settings'
  ] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS resort_audit ON %I', v_table);
    EXECUTE format(
      'CREATE TRIGGER resort_audit AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION resort_audit_row_change()',
      v_table
    );
  END LOOP;
END $$;

-- ------------------------------------------------------------
-- Grants: service role only.
-- ------------------------------------------------------------
DO $$
DECLARE
  v_fn TEXT;
BEGIN
  FOREACH v_fn IN ARRAY ARRAY[
    'public.resort_lock_estate(uuid)',
    'public.resort_expire_stale_holds(uuid)',
    'public.resort_find_conflicts(uuid, timestamptz, timestamptz, uuid)',
    'public.resort_reserve(uuid, text, uuid, timestamptz, timestamptz, timestamptz, text, uuid)',
    'public.resort_release_booking(uuid, uuid)',
    'public.resort_recompute_booking_money(uuid)',
    'public.resort_apply_verified_payment(text, text, bigint, text, text)',
    'public.resort_confirm_booking(uuid, uuid, uuid)',
    'public.resort_claim_notification_jobs(integer)'
  ] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO postgres', v_fn);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated', v_fn);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', v_fn);
  END LOOP;
END $$;

ALTER FUNCTION public.resort_audit_row_change() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.resort_audit_row_change() FROM PUBLIC, anon, authenticated;

-- >>>>>>>>>> 061_vfarms_bot_test_numbers.sql
-- ============================================================
-- 061: V-Farms bot test allowlist
--
-- While property_settings.test_mode is on, the WhatsApp bot records its
-- replies in the inbox without sending them, except to the staff phone
-- numbers listed here (E.164), so the owner can try the bot end-to-end
-- from their own phone without messaging real guests.
-- ============================================================

ALTER TABLE property_settings
  ADD COLUMN IF NOT EXISTS test_phone_numbers TEXT[] NOT NULL DEFAULT '{}';

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'property_settings_test_numbers_e164') THEN
    ALTER TABLE property_settings ADD CONSTRAINT property_settings_test_numbers_e164
      CHECK (array_to_string(test_phone_numbers, ',') ~ '^(\+[1-9][0-9]{7,14}(,\+[1-9][0-9]{7,14})*)?$');
  END IF;
END $$;

-- >>>>>>>>>> 062_redeem_invitation_resort_guard.sql
-- ============================================================
-- 062_redeem_invitation_resort_guard.sql
--
-- redeem_invitation deletes the caller's old (empty) account when they
-- join another one. Migration 059 added account-scoped resort tables
-- (property, pricing, leads, bookings, payments, ...); an account holding
-- any of that data must not be treated as empty, or the delete would
-- cascade through it. This adds those tables to the "has data" guard.
-- The function is otherwise identical to migration 057.
--
-- Idempotent — safe to run multiple times.
-- ============================================================

CREATE OR REPLACE FUNCTION public.redeem_invitation(
  p_token_hash TEXT
) RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_inv account_invitations%ROWTYPE;
  v_old_account_id UUID;
  v_old_account_owner UUID;
  v_has_other_members BOOLEAN;
  v_has_data BOOLEAN;
BEGIN
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_inv
  FROM account_invitations
  WHERE token_hash = p_token_hash
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitation not found' USING ERRCODE = '22023';
  END IF;
  IF v_inv.accepted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Invitation has already been redeemed'
      USING ERRCODE = '22023';
  END IF;
  IF v_inv.expires_at IS NOT NULL AND v_inv.expires_at <= NOW() THEN
    RAISE EXCEPTION 'Invitation has expired' USING ERRCODE = '22023';
  END IF;

  SELECT p.account_id, a.owner_user_id
  INTO v_old_account_id, v_old_account_owner
  FROM profiles p
  JOIN accounts a ON a.id = p.account_id
  WHERE p.user_id = v_caller_id
  FOR UPDATE OF p, a;

  IF v_old_account_id IS NULL THEN
    RAISE EXCEPTION 'Caller has no profile' USING ERRCODE = '42501';
  END IF;

  IF v_old_account_id = v_inv.account_id THEN
    RAISE EXCEPTION 'You are already a member of this account'
      USING ERRCODE = '23505';
  END IF;

  IF v_old_account_owner <> v_caller_id THEN
    RAISE EXCEPTION 'You are already in a shared account; sign up with a different email to join this one'
      USING ERRCODE = '23505';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE account_id = v_old_account_id
      AND user_id <> v_caller_id
  ) INTO v_has_other_members;

  IF v_has_other_members THEN
    RAISE EXCEPTION 'Your account has other members; remove them or transfer ownership before joining another account'
      USING ERRCODE = '23505';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM contacts WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM conversations WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM broadcasts WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM automations WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM automation_logs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM automation_pending_executions WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM flows WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM flow_runs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM pipelines WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM deals WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM message_templates WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM tags WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM custom_fields WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM contact_notes WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM whatsapp_config WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM api_keys WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM webhook_endpoints WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM quick_replies WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM notifications WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM ai_configs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM ai_knowledge_documents WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM ai_knowledge_chunks WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM ai_usage_log WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM property_settings WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM property_media WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM amenities WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM property_faqs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM pricing_rules WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM seasonal_rates WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM event_packages WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM addons WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM leads WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM lead_notes WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM conversation_states WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM bookings WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM booking_guests WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM booking_quotes WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM event_requests WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM availability_blocks WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM payments WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM refunds WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM notification_jobs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM audit_logs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM webhook_events WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM consent_records WHERE account_id = v_old_account_id
    LIMIT 1
  ) INTO v_has_data;

  IF v_has_data THEN
    RAISE EXCEPTION 'Your account already contains data; sign up with a different email to join this one'
      USING ERRCODE = '23505';
  END IF;

  UPDATE profiles
  SET account_id = v_inv.account_id,
      account_role = v_inv.role
  WHERE user_id = v_caller_id;

  UPDATE account_invitations
  SET accepted_at = NOW(),
      accepted_by_user_id = v_caller_id
  WHERE id = v_inv.id;

  DELETE FROM accounts WHERE id = v_old_account_id;

  RETURN v_inv.account_id;
END;
$$;

ALTER FUNCTION public.redeem_invitation(TEXT) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.redeem_invitation(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.redeem_invitation(TEXT) TO authenticated;

-- >>>>>>>>>> 063_vfarms_resort_automations.sql
-- ============================================================
-- V-Farms resort automations (A–L).
--
-- resort_automations is the per-account registry the Automations page
-- shows: one row per resort automation, disabled by default, with a
-- validated config and persisted counters. resort_automation_runs is the
-- execution history; a trigger keeps the counters in step, and
-- (account_id, dedupe_key) makes a repeated webhook / cron pass record
-- the same execution once.
--
-- Also adds: guest feedback, cancellation / reschedule requests, the
-- payment-exception record staff give when confirming without the
-- advance, follow-up counters on leads, three new guest-message kinds,
-- and an archive marker on automations (used by
-- scripts/archive-solar-records.mjs; nothing is archived here).
--
-- Idempotent. Rollback: supabase/rollback/063_vfarms_resort_automations_down.sql
-- ============================================================

-- Same-named tables that predate this migration are kept as
-- legacy_pre_vfarms_<name> (see 059). No-op once resort_automations exists.
DO $$
DECLARE
  t TEXT;
  r RECORD;
BEGIN
  IF to_regclass('public.resort_automations') IS NOT NULL THEN
    RETURN;
  END IF;
  FOREACH t IN ARRAY ARRAY['resort_automation_runs', 'booking_feedback', 'booking_change_requests', 'legacy_archive'] LOOP
    CONTINUE WHEN to_regclass(format('public.%I', t)) IS NULL;
    IF to_regclass(format('public.%I', 'legacy_pre_vfarms_' || t)) IS NOT NULL THEN
      RAISE EXCEPTION 'public.% predates V-Farms and public.legacy_pre_vfarms_% already exists; rename one of them and re-run.', t, t;
    END IF;
    FOR r IN
      SELECT c.relname, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'INDEX' END AS kind
      FROM pg_class c
      WHERE c.oid IN (SELECT indexrelid FROM pg_index WHERE indrelid = format('public.%I', t)::regclass)
         OR c.oid IN (SELECT objid FROM pg_depend WHERE refobjid = format('public.%I', t)::regclass AND deptype IN ('a', 'i') AND classid = 'pg_class'::regclass)
            AND c.relkind = 'S'
    LOOP
      EXECUTE format('ALTER %s public.%I RENAME TO %I', r.kind, r.relname, left('legacy_pre_vfarms_' || r.relname, 63));
    END LOOP;
    EXECUTE format('ALTER TABLE public.%I RENAME TO %I', t, 'legacy_pre_vfarms_' || t);
    RAISE NOTICE 'Kept pre-existing public.% as public.legacy_pre_vfarms_% (data untouched).', t, t;
  END LOOP;
END $$;

-- ---- Guest message kinds -----------------------------------------
ALTER TABLE notification_jobs DROP CONSTRAINT IF EXISTS notification_jobs_kind_check;
ALTER TABLE notification_jobs ADD CONSTRAINT notification_jobs_kind_check CHECK (kind IN (
  'new_enquiry', 'qualified_lead', 'quote_requested', 'booking_requested',
  'payment_verified', 'booking_confirmed', 'upcoming_arrival', 'upcoming_checkout',
  'event_approval_required', 'cancellation_requested', 'message_failed', 'handoff_requested',
  'payment_reminder', 'post_stay_feedback', 'enquiry_followup', 'reschedule_requested'
));

-- ---- Automation registry -----------------------------------------
CREATE TABLE IF NOT EXISTS resort_automations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  key TEXT NOT NULL CHECK (key IN (
    'welcome_menu', 'stay_enquiry', 'availability_check', 'pricing_quote', 'event_enquiry',
    'human_escalation', 'booking_confirmation', 'payment_reminder', 'pre_arrival_reminder',
    'post_stay_feedback', 'abandoned_followup', 'cancel_reschedule'
  )),
  name TEXT NOT NULL,
  description TEXT,
  trigger_type TEXT NOT NULL,
  is_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  config JSONB NOT NULL DEFAULT '{}'::jsonb,
  execution_count INTEGER NOT NULL DEFAULT 0 CHECK (execution_count >= 0),
  success_count INTEGER NOT NULL DEFAULT 0 CHECK (success_count >= 0),
  failure_count INTEGER NOT NULL DEFAULT 0 CHECK (failure_count >= 0),
  skipped_count INTEGER NOT NULL DEFAULT 0 CHECK (skipped_count >= 0),
  last_executed_at TIMESTAMPTZ,
  last_status TEXT CHECK (last_status IS NULL OR last_status IN ('success', 'failed', 'skipped')),
  last_error TEXT,
  updated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT resort_automations_one_per_key UNIQUE (account_id, key)
);

CREATE TABLE IF NOT EXISTS resort_automation_runs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  automation_key TEXT NOT NULL,
  trigger TEXT NOT NULL,
  -- test: a manual Run Test preview; never counted, never sends.
  status TEXT NOT NULL CHECK (status IN ('success', 'failed', 'skipped', 'test')),
  dedupe_key TEXT,
  conversation_id UUID REFERENCES conversations(id) ON DELETE SET NULL,
  contact_id UUID REFERENCES contacts(id) ON DELETE SET NULL,
  booking_id UUID REFERENCES bookings(id) ON DELETE SET NULL,
  lead_id UUID REFERENCES leads(id) ON DELETE SET NULL,
  detail JSONB NOT NULL DEFAULT '{}'::jsonb,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT resort_automation_runs_dedupe UNIQUE (account_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_resort_automation_runs_key
  ON resort_automation_runs(account_id, automation_key, created_at DESC);

CREATE OR REPLACE FUNCTION public.resort_automation_run_counter()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.status = 'test' THEN
    RETURN NEW;
  END IF;
  UPDATE resort_automations
     SET execution_count = execution_count + 1,
         success_count = success_count + (NEW.status = 'success')::int,
         failure_count = failure_count + (NEW.status = 'failed')::int,
         skipped_count = skipped_count + (NEW.status = 'skipped')::int,
         last_executed_at = NEW.created_at,
         last_status = NEW.status,
         last_error = CASE WHEN NEW.status = 'failed' THEN left(NEW.error, 500) ELSE NULL END
   WHERE account_id = NEW.account_id AND key = NEW.automation_key;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS resort_automation_run_counter ON resort_automation_runs;
CREATE TRIGGER resort_automation_run_counter
  AFTER INSERT ON resort_automation_runs
  FOR EACH ROW EXECUTE FUNCTION public.resort_automation_run_counter();

ALTER FUNCTION public.resort_automation_run_counter() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.resort_automation_run_counter() FROM PUBLIC, anon, authenticated;

-- ---- Guest feedback (post-stay) ----------------------------------
CREATE TABLE IF NOT EXISTS booking_feedback (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  booking_id UUID NOT NULL UNIQUE REFERENCES bookings(id) ON DELETE CASCADE,
  contact_id UUID REFERENCES contacts(id) ON DELETE SET NULL,
  rating INTEGER CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  comment TEXT CHECK (comment IS NULL OR length(comment) <= 2000),
  source TEXT NOT NULL DEFAULT 'whatsapp' CHECK (source IN ('whatsapp', 'staff')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ---- Cancellation / reschedule requests --------------------------
-- A guest request is recorded here; only an authorised staff action
-- changes the booking itself.
CREATE TABLE IF NOT EXISTS booking_change_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('cancel', 'reschedule')),
  requested_check_in DATE,
  requested_check_out DATE,
  requested_event_date DATE,
  -- Live result at request time: available | unavailable | pending_manual | unknown.
  availability_status TEXT,
  quote_snapshot JSONB,
  reason TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'withdrawn')),
  source TEXT NOT NULL DEFAULT 'whatsapp' CHECK (source IN ('whatsapp', 'staff')),
  reviewed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  reviewed_at TIMESTAMPTZ,
  review_notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT booking_change_requests_dates CHECK (
    requested_check_in IS NULL OR requested_check_out IS NULL OR requested_check_out > requested_check_in
  )
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_booking_change_requests_one_pending
  ON booking_change_requests(booking_id) WHERE status = 'pending';

-- ---- Payment exception / follow-up tracking ----------------------
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS payment_exception_note TEXT;
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS payment_exception_by UUID REFERENCES auth.users(id) ON DELETE SET NULL;
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS payment_exception_at TIMESTAMPTZ;

ALTER TABLE leads ADD COLUMN IF NOT EXISTS follow_up_count INTEGER NOT NULL DEFAULT 0;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS last_follow_up_at TIMESTAMPTZ;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'leads_follow_up_count_nonneg') THEN
    ALTER TABLE leads ADD CONSTRAINT leads_follow_up_count_nonneg CHECK (follow_up_count >= 0);
  END IF;
END $$;

-- ---- Archive marker for retired (e.g. Suraj Solar) automations ---
ALTER TABLE automations ADD COLUMN IF NOT EXISTS archived_at TIMESTAMPTZ;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'automations_archived_inactive') THEN
    ALTER TABLE automations ADD CONSTRAINT automations_archived_inactive
      CHECK (archived_at IS NULL OR is_active = FALSE);
  END IF;
END $$;

-- Snapshots of rows removed by the archive script, so they can be restored.
CREATE TABLE IF NOT EXISTS legacy_archive (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID REFERENCES accounts(id) ON DELETE CASCADE,
  source_table TEXT NOT NULL,
  source_id UUID NOT NULL,
  snapshot JSONB NOT NULL,
  reason TEXT NOT NULL,
  archived_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  restored_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_legacy_archive_source ON legacy_archive(source_table, source_id);

-- ---- updated_at --------------------------------------------------
DO $$
DECLARE
  v_table TEXT;
BEGIN
  FOREACH v_table IN ARRAY ARRAY['resort_automations', 'booking_change_requests'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS set_updated_at ON %I', v_table);
    EXECUTE format(
      'CREATE TRIGGER set_updated_at BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()',
      v_table
    );
  END LOOP;
END $$;

-- ---- Row level security ------------------------------------------
-- Registry: members read, admins change (enable / config). Rows are
-- created by the server. Runs, feedback, change requests and the
-- archive are written by the server only.
ALTER TABLE resort_automations ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS resort_automations_select ON resort_automations;
DROP POLICY IF EXISTS resort_automations_update ON resort_automations;
CREATE POLICY resort_automations_select ON resort_automations FOR SELECT
  USING (is_account_member(account_id));
CREATE POLICY resort_automations_update ON resort_automations FOR UPDATE
  USING (is_account_member(account_id, 'admin')) WITH CHECK (is_account_member(account_id, 'admin'));

ALTER TABLE resort_automation_runs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS resort_automation_runs_select ON resort_automation_runs;
CREATE POLICY resort_automation_runs_select ON resort_automation_runs FOR SELECT
  USING (is_account_member(account_id, 'agent'));

ALTER TABLE booking_feedback ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS booking_feedback_select ON booking_feedback;
CREATE POLICY booking_feedback_select ON booking_feedback FOR SELECT
  USING (is_account_member(account_id));

ALTER TABLE booking_change_requests ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS booking_change_requests_select ON booking_change_requests;
CREATE POLICY booking_change_requests_select ON booking_change_requests FOR SELECT
  USING (is_account_member(account_id));

ALTER TABLE legacy_archive ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS legacy_archive_select ON legacy_archive;
CREATE POLICY legacy_archive_select ON legacy_archive FOR SELECT
  USING (account_id IS NOT NULL AND is_account_member(account_id, 'admin'));

REVOKE INSERT, DELETE ON resort_automations FROM anon, authenticated;
REVOKE INSERT, UPDATE, DELETE ON resort_automation_runs, booking_feedback, booking_change_requests, legacy_archive
  FROM anon, authenticated;

-- >>>>>>>>>> 064_redeem_invitation_automation_guard.sql
-- ============================================================
-- 064_redeem_invitation_automation_guard.sql
--
-- Migration 063 added account-scoped tables (resort automation registry,
-- run history, feedback, change requests, legacy archive). An account
-- holding any of that data must not be treated as empty by
-- redeem_invitation. The function is otherwise identical to migration 062.
-- Rollback: re-run migration 062 (before 063's rollback).
--
-- Idempotent — safe to run multiple times.
-- ============================================================

CREATE OR REPLACE FUNCTION public.redeem_invitation(
  p_token_hash TEXT
) RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_inv account_invitations%ROWTYPE;
  v_old_account_id UUID;
  v_old_account_owner UUID;
  v_has_other_members BOOLEAN;
  v_has_data BOOLEAN;
BEGIN
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_inv
  FROM account_invitations
  WHERE token_hash = p_token_hash
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitation not found' USING ERRCODE = '22023';
  END IF;
  IF v_inv.accepted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Invitation has already been redeemed'
      USING ERRCODE = '22023';
  END IF;
  IF v_inv.expires_at IS NOT NULL AND v_inv.expires_at <= NOW() THEN
    RAISE EXCEPTION 'Invitation has expired' USING ERRCODE = '22023';
  END IF;

  SELECT p.account_id, a.owner_user_id
  INTO v_old_account_id, v_old_account_owner
  FROM profiles p
  JOIN accounts a ON a.id = p.account_id
  WHERE p.user_id = v_caller_id
  FOR UPDATE OF p, a;

  IF v_old_account_id IS NULL THEN
    RAISE EXCEPTION 'Caller has no profile' USING ERRCODE = '42501';
  END IF;

  IF v_old_account_id = v_inv.account_id THEN
    RAISE EXCEPTION 'You are already a member of this account'
      USING ERRCODE = '23505';
  END IF;

  IF v_old_account_owner <> v_caller_id THEN
    RAISE EXCEPTION 'You are already in a shared account; sign up with a different email to join this one'
      USING ERRCODE = '23505';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE account_id = v_old_account_id
      AND user_id <> v_caller_id
  ) INTO v_has_other_members;

  IF v_has_other_members THEN
    RAISE EXCEPTION 'Your account has other members; remove them or transfer ownership before joining another account'
      USING ERRCODE = '23505';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM contacts WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM conversations WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM broadcasts WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM automations WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM automation_logs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM automation_pending_executions WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM flows WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM flow_runs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM pipelines WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM deals WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM message_templates WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM tags WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM custom_fields WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM contact_notes WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM whatsapp_config WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM api_keys WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM webhook_endpoints WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM quick_replies WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM notifications WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM ai_configs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM ai_knowledge_documents WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM ai_knowledge_chunks WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM ai_usage_log WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM property_settings WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM property_media WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM amenities WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM property_faqs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM pricing_rules WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM seasonal_rates WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM event_packages WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM addons WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM leads WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM lead_notes WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM conversation_states WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM bookings WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM booking_guests WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM booking_quotes WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM event_requests WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM availability_blocks WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM payments WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM refunds WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM notification_jobs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM audit_logs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM webhook_events WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM consent_records WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM resort_automations WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM resort_automation_runs WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM booking_feedback WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM booking_change_requests WHERE account_id = v_old_account_id
    UNION ALL SELECT 1 FROM legacy_archive WHERE account_id = v_old_account_id
    LIMIT 1
  ) INTO v_has_data;

  IF v_has_data THEN
    RAISE EXCEPTION 'Your account already contains data; sign up with a different email to join this one'
      USING ERRCODE = '23505';
  END IF;

  UPDATE profiles
  SET account_id = v_inv.account_id,
      account_role = v_inv.role
  WHERE user_id = v_caller_id;

  UPDATE account_invitations
  SET accepted_at = NOW(),
      accepted_by_user_id = v_caller_id
  WHERE id = v_inv.id;

  DELETE FROM accounts WHERE id = v_old_account_id;

  RETURN v_inv.account_id;
END;
$$;

ALTER FUNCTION public.redeem_invitation(TEXT) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.redeem_invitation(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.redeem_invitation(TEXT) TO authenticated;

-- >>>>>>>>>> 065_vfarms_booking_request_flow.sql
-- ============================================================
-- V-Farms: "Booking Request" becomes its own resort flow (key
-- booking_request), separate from "Booking Confirmation". It gates the
-- guest's "Request booking" step, which places a temporary hold through
-- resort_reserve(); when disabled the request goes to the team and
-- nothing is held. Registry rows are created disabled by the app.
--
-- Idempotent. Rollback: supabase/rollback/065_vfarms_booking_request_flow_down.sql
-- ============================================================

ALTER TABLE resort_automations DROP CONSTRAINT IF EXISTS resort_automations_key_check;
ALTER TABLE resort_automations ADD CONSTRAINT resort_automations_key_check CHECK (key IN (
  'welcome_menu', 'stay_enquiry', 'availability_check', 'pricing_quote', 'event_enquiry',
  'human_escalation', 'booking_request', 'booking_confirmation', 'payment_reminder',
  'pre_arrival_reminder', 'post_stay_feedback', 'abandoned_followup', 'cancel_reschedule'
));

COMMIT;
